// Every step reports exactly one result, so recording it is the one thing the
// two step kinds always have in common — named once here rather than rebuilt in
// each of them.
const withResultRecorded = (state: ScenarioState, result: Result): ScenarioState => ({
  ...state,
  results: [...state.results, result],
});

const afterQuote = (
  state: ScenarioState,
  items: Item[],
  customer: Customer,
  stepIndex: number,
): ScenarioState => ({
  ...withResultRecorded(
    state,
    quoteFor(items, { customer, precedingQuotes: state.precedingQuotes }),
  ),
  precedingQuotes: state.precedingQuotes + 1,
  policies: { ...state.policies, [stepIndex]: policyFor(items) },
});

const afterClaim = (
  state: ScenarioState,
  policyIndex: number,
  incident: Incident,
): ScenarioState => {
  const [result, settledPolicy] = claimFor(incident, state.policies[policyIndex]);
  return {
    ...withResultRecorded(state, result),
    policies: { ...state.policies, [policyIndex]: settledPolicy },
  };
};

